readCsv = async f =&gt; d3.csvParse((await f.text()).replace(/^\uFEFF/, ""))
taxonomy = readCsv(FileAttachment("data/network-taxonomy.csv"))
items = readCsv(FileAttachment("data/network-items.csv"))
network = {

  // Each theme is a color family; its categories step from the darker to the lighter tone.
  // "text" is the shade used for the theme label and panel headings (readable on white).
  const themeRamps = new Map([
    ["Partnerships", { dark: "#4B0082", light: "#9B59D0", text: "#4B0082" }],
    ["Topics",       { dark: "#C2410C", light: "#FDA34B", text: "#C2410C" }],
    ["Method", { dark: "#C2185B", light: "#F7A8C8", text: "#C2185B" }],
    ["Disciplines",  { dark: "#B8860B", light: "#FFD84D", text: "#9A7000" }]
  ]);
  const typeLabels = {
    article: "Journal article",
    wip: "Work in progress",
    chapter: "Book or chapter",
    presentation: "Conference presentation"
  };

  // Build categories and attach each work to the categories marked in its row
  const subs = taxonomy.map(d =&gt; ({ theme: d.theme, group: (d.group || "").trim(), name: d.subtopic, label: d.label || d.subtopic, members: [] }));
  const subByName = new Map(subs.map(s =&gt; [s.name, s]));
  // Match column names loosely: ignore case, extra spaces, and "&" vs "and"
  const norm = x =&gt; (x || "").toLowerCase().replace(/&/g, " and ").replace(/\s+/g, " ").trim();
  const colFor = new Map(items.columns.map(c =&gt; [norm(c), c]));
  subs.forEach(s =&gt; s.column = colFor.get(norm(s.name)));
  subs.filter(s =&gt; !s.column).forEach(s =&gt; console.warn(`Category "${s.name}" has no matching column in network-items.csv`));
  const known = new Set(["type", "title", "authors", "venue", "year", "link", ...subs.map(s =&gt; s.column)]);
  items.columns.filter(c =&gt; !known.has(c)).forEach(c =&gt; console.warn(`Column "${c}" in network-items.csv is not in network-taxonomy.csv`));
  const papers = items.map((d, i) =&gt; ({
    ...d, id: i,
    tagList: subs.filter(s =&gt; s.column && /^(x|yes|y|1|true)$/i.test((d[s.column] || "").trim())).map(s =&gt; s.name),
    dots: []
  }));
  for (const p of papers) {
    for (const t of p.tagList) {
      subByName.get(t).members.push(p);
    }
  }

  // Lay subtopics around the circle. Each gets room for its dots and for its label,
  // measured in the page's actual font so labels never run into each other
  await document.fonts.ready;
  const ctx = document.createElement("canvas").getContext("2d");
  ctx.font = `17px ${getComputedStyle(document.body).fontFamily}`;
  const textW = t =&gt; ctx.measureText(t).width;
  const dotPx = 13, gapSubPx = 10, gapThemePx = 40, labelPad = 18;
  subs.forEach(s =&gt; s.px = Math.max((s.members.length + 1) * dotPx, textW(s.label) + labelPad));
  const gapAfter = subs.map((s, i) =&gt; subs[(i + 1) % subs.length].theme !== s.theme ? gapThemePx : gapSubPx);
  const totalPx = d3.sum(subs, s =&gt; s.px) + d3.sum(gapAfter);
  // The circle grows when the labels need more room than the default radius allows
  const R = Math.max(380, totalPx / (2 * Math.PI));
  const W = 2 * R + 540, H = 2 * R + 480, cx = W / 2, cy = H / 2;
  const dotR = R - 14, subR = R * 0.62, themeR = R * 0.28;
  const scale = (2 * Math.PI * R) / totalPx;
  const toAng = px =&gt; (px * scale) / R;
  let a = toAng(gapAfter[gapAfter.length - 1] / 2);
  subs.forEach((s, i) =&gt; {
    s.a0 = a;
    s.a1 = a + toAng(s.px);
    s.mid = (s.a0 + s.a1) / 2;
    const step = toAng(dotPx);
    const start = s.mid - (step * (s.members.length - 1)) / 2;
    s.members.forEach((p, j) =&gt; p.dots.push({ paper: p, sub: s, angle: start + j * step }));
    a = s.a1 + toAng(gapAfter[i]);
  });
  const themes = Array.from(d3.group(subs, s =&gt; s.theme), ([name, ss]) =&gt; ({
    name, subs: ss, a0: d3.min(ss, s =&gt; s.a0), a1: d3.max(ss, s =&gt; s.a1),
    ramp: themeRamps.get(name) || { dark: "#57068c", light: "#b48ad9", text: "#57068c" }
  }));
  themes.forEach(t =&gt; { t.mid = (t.a0 + t.a1) / 2; t.color = t.ramp.text; });
  const themeByName = new Map(themes.map(t =&gt; [t.name, t]));
  subs.forEach(s =&gt; {
    const t = themeByName.get(s.theme);
    const k = t.subs.indexOf(s);
    s.color = d3.interpolateRgb(t.ramp.dark, t.ramp.light)(t.subs.length &gt; 1 ? k / (t.subs.length - 1) : 0);
  });

  const pt = (ang, r) =&gt; [cx + r * Math.sin(ang), cy - r * Math.cos(ang)];
  const dots = papers.flatMap(p =&gt; p.dots);

  // One curve for every pair of subtopics a work belongs to, bundled through its themes
  const line = d3.line().curve(d3.curveBundle.beta(0.85));
  const links = [];
  for (const p of papers) {
    for (let i = 0; i &lt; p.dots.length; i++) {
      for (let j = i + 1; j &lt; p.dots.length; j++) {
        const A = p.dots[i], B = p.dots[j];
        const tA = themeByName.get(A.sub.theme), tB = themeByName.get(B.sub.theme);
        const pts = [pt(A.angle, dotR - 6), pt(A.sub.mid, subR), pt(tA.mid, themeR)];
        if (tA !== tB) pts.push(pt(tB.mid, themeR));
        pts.push(pt(B.sub.mid, subR), pt(B.angle, dotR - 6));
        links.push({ paper: p, d: line(pts), color: tA.color });
      }
    }
  }

  // Layout: compact info panel in the top-left corner, diagram to the right, and a
  // button in the top-right corner that expands the whole piece to full screen
  const root = html`&lt;div class="network-wrap"&gt;&lt;/div&gt;`;
  const panel = html`&lt;div class="network-panel" aria-live="polite"&gt;&lt;/div&gt;`;
  const fsButton = html`&lt;button type="button" class="network-fs-btn" aria-label="View full screen" title="View full screen"&gt;&lt;i class="bi bi-arrows-angle-expand"&gt;&lt;/i&gt;&lt;/button&gt;`;
  root.append(panel, fsButton);
  const setExpanded = on =&gt; {
    root.classList.toggle("is-expanded", on);
    document.body.classList.toggle("network-expanded", on);
    fsButton.innerHTML = on ? '&lt;i class="bi bi-arrows-angle-contract"&gt;&lt;/i&gt;' : '&lt;i class="bi bi-arrows-angle-expand"&gt;&lt;/i&gt;';
    fsButton.setAttribute("aria-label", on ? "Exit full screen" : "View full screen");
    fsButton.title = on ? "Exit full screen (Esc)" : "View full screen";
  };
  fsButton.addEventListener("click", async () =&gt; {
    const on = !root.classList.contains("is-expanded");
    if (on) {
      setExpanded(true);
      try { if (root.requestFullscreen) await root.requestFullscreen(); } catch (e) { /* overlay still works */ }
    } else {
      if (document.fullscreenElement) await document.exitFullscreen();
      setExpanded(false);
    }
  });
  // Leaving browser full screen (Esc) also collapses the piece
  document.addEventListener("fullscreenchange", () =&gt; { if (!document.fullscreenElement) setExpanded(false); });
  document.addEventListener("keydown", e =&gt; { if (e.key === "Escape" && root.classList.contains("is-expanded")) setExpanded(false); });
  const svg = d3.select(root).append("svg")
    .attr("viewBox", `0 0 ${W} ${H}`)
    .attr("class", "network-svg")
    .attr("role", "img")
    .attr("aria-label", "Diagram connecting my publications and presentations to the partnerships, topics, methods, and disciplines they draw on");

  const linkSel = svg.append("g").attr("fill", "none")
    .selectAll("path").data(links).join("path")
    .attr("d", d =&gt; d.d)
    .attr("stroke", "currentColor")
    .attr("stroke-opacity", 0.09)
    .attr("stroke-width", 1);

  svg.append("g").selectAll("path").data(subs).join("path")
    .attr("transform", `translate(${cx},${cy})`)
    .attr("d", s =&gt; d3.arc().innerRadius(R).outerRadius(R + 9).startAngle(s.a0).endAngle(s.a1).cornerRadius(2)())
    .attr("fill", s =&gt; s.color)
    .style("cursor", "pointer")
    .on("mouseenter", (e, s) =&gt; preview({ sub: s }))
    .on("mouseleave", restore)
    .on("click", (e, s) =&gt; { e.stopPropagation(); togglePin({ sub: s }); });

  // Labels follow the arc. Each theme reads in one direction: themes centered near the
  // bottom are flipped so their labels read upright; side themes read top to bottom
  const defs = svg.append("defs");
  const arcPath = (r, a0, a1, flip) =&gt; {
    const [x0, y0] = pt(flip ? a1 : a0, r), [x1, y1] = pt(flip ? a0 : a1, r);
    const large = Math.abs(a1 - a0) &gt; Math.PI ? 1 : 0;
    return `M${x0},${y0} A${r},${r} 0 ${large} ${flip ? 0 : 1} ${x1},${y1}`;
  };
  subs.forEach((s, i) =&gt; {
    const tm = themeByName.get(s.theme).mid;
    const flip = s.flip = tm &gt; 0.6 * Math.PI && tm &lt; 1.4 * Math.PI;
    s.labelId = `net-sub-${i}`;
    defs.append("path").attr("id", s.labelId)
      .attr("d", arcPath(flip ? R + 30 : R + 18, s.a0 - 0.4, s.a1 + 0.4, flip));
  });
  svg.append("g").selectAll("text").data(subs).join("text")
    .attr("class", "network-sub-label")
    .append("textPath")
    .attr("href", s =&gt; `#${s.labelId}`)
    .attr("startOffset", "50%")
    .attr("text-anchor", "middle")
    .text(s =&gt; s.label);

  // Optional middle layer within a theme (the "group" column in network-taxonomy.csv)
  themes.forEach(t =&gt; {
    t.groups = [];
    t.subs.forEach(s =&gt; {
      if (!s.group) return;
      const last = t.groups[t.groups.length - 1];
      if (last && last.name === s.group) { last.a1 = s.a1; last.subs.push(s); }
      else t.groups.push({ name: s.group, theme: t, a0: s.a0, a1: s.a1, subs: [s] });
    });
  });
  const groups = themes.flatMap(t =&gt; t.groups);
  groups.forEach((g, i) =&gt; {
    g.mid = (g.a0 + g.a1) / 2;
    g.flip = g.subs[0].flip;
    g.labelId = `net-group-${i}`;
    defs.append("path").attr("id", g.labelId)
      .attr("d", arcPath(g.flip ? R + 70 : R + 57, g.a0 - 0.4, g.a1 + 0.4, g.flip));
  });
  svg.append("g").selectAll("path").data(groups).join("path")
    .attr("transform", `translate(${cx},${cy})`)
    .attr("d", g =&gt; d3.arc().innerRadius(R + 43).outerRadius(R + 46).startAngle(g.a0).endAngle(g.a1)())
    .attr("fill", g =&gt; g.theme.color)
    .attr("fill-opacity", 0.6);
  svg.append("g").selectAll("text").data(groups).join("text")
    .attr("class", "network-group-label")
    .attr("fill", g =&gt; g.theme.color)
    .append("textPath")
    .attr("href", g =&gt; `#${g.labelId}`)
    .attr("startOffset", "50%")
    .attr("text-anchor", "middle")
    .text(g =&gt; g.name);
  svg.append("g").selectAll("text").data(themes).join("text")
    .attr("class", "network-theme-label")
    .attr("x", t =&gt; pt(t.mid, t.groups.length ? R + 104 : R + 70)[0])
    .attr("y", t =&gt; pt(t.mid, t.groups.length ? R + 104 : R + 70)[1])
    .attr("text-anchor", t =&gt; Math.sin(t.mid) &gt; 0.2 ? "start" : Math.sin(t.mid) &lt; -0.2 ? "end" : "middle")
    .attr("dominant-baseline", "middle")
    .attr("fill", t =&gt; t.color)
    .text(t =&gt; t.name);

  const dotSel = svg.append("g").selectAll("circle").data(dots).join("circle")
    .attr("cx", d =&gt; pt(d.angle, dotR)[0])
    .attr("cy", d =&gt; pt(d.angle, dotR)[1])
    .attr("r", 5)
    .style("fill", d =&gt; d.paper.type === "presentation" ? "var(--bs-body-bg, #fff)" : d.sub.color)
    .attr("fill-opacity", d =&gt; d.paper.type === "presentation" ? 1 : 0.55)
    .attr("stroke", d =&gt; d.sub.color)
    .attr("stroke-width", d =&gt; d.paper.type === "presentation" ? 1.6 : 0)
    .style("cursor", "pointer")
    .on("mouseenter", (e, d) =&gt; preview({ paper: d.paper }))
    .on("mouseleave", restore)
    .on("click", (e, d) =&gt; { e.stopPropagation(); togglePin({ paper: d.paper }); });

  // Clicking empty space in the diagram clears a pinned selection
  svg.on("click", () =&gt; { if (pinned) { pinned = null; restore(); } });

  // Info panel content
  const clearButton = () =&gt; {
    const b = html`&lt;button type="button" class="network-clear"&gt;Clear selection ×&lt;/button&gt;`;
    b.addEventListener("click", () =&gt; { pinned = null; restore(); });
    return b;
  };
  const defaultPanel = () =&gt; {
    panel.innerHTML = "";
    panel.append(html`&lt;div class="network-kicker"&gt;Explore my work&lt;/div&gt;
      &lt;p class="network-help"&gt;Each dot is one of my papers or presentations. Hover over one to explore how each project draws on different topics, methods, and disciplines, and whether it was conducted in partnership with an agency. Hover over an arc to see everything I've done in that area.&lt;/p&gt;
      &lt;p class="network-legend"&gt;&lt;span class="dot filled"&gt;&lt;/span&gt; Paper or chapter &nbsp; &lt;span class="dot hollow"&gt;&lt;/span&gt; Presentation&lt;/p&gt;
      &lt;p class="network-hint"&gt;Click a dot or arc to keep it selected.&lt;/p&gt;`);
  };
  const showPaper = (p, isPinned) =&gt; {
    panel.innerHTML = "";
    const tagsByTheme = themes
      .map(t =&gt; ({ t, tags: p.tagList.filter(x =&gt; subByName.get(x)?.theme === t.name) }))
      .filter(g =&gt; g.tags.length);
    panel.append(html`&lt;div class="network-kicker"&gt;${typeLabels[p.type] || ""}&lt;/div&gt;
      &lt;div class="network-title"&gt;${p.title}&lt;/div&gt;
      &lt;div class="network-meta"&gt;${p.authors}${p.year ? ` (${p.year})` : ""} · &lt;em&gt;${p.venue}&lt;/em&gt;&lt;/div&gt;
      &lt;div class="network-tags"&gt;${tagsByTheme.map(g =&gt; html`&lt;div&gt;&lt;span style="color:${g.t.color}"&gt;${g.t.name}:&lt;/span&gt; ${g.tags.join(", ")}&lt;/div&gt;`)}&lt;/div&gt;
      ${p.link ? html`&lt;div class="network-link"&gt;&lt;a href="${p.link}" target="_blank" rel="noopener"&gt;Open this ${p.type === "presentation" ? "presentation" : "paper"} ↗&lt;/a&gt;&lt;/div&gt;` : ""}
      ${isPinned ? "" : html`&lt;p class="network-hint"&gt;Click the dot to keep this open.&lt;/p&gt;`}`);
    if (isPinned) panel.append(clearButton());
  };
  const showSub = (s, isPinned) =&gt; {
    panel.innerHTML = "";
    const list = html`&lt;ul class="network-list"&gt;${s.members.map(p =&gt; html`&lt;li&gt;&lt;button type="button" class="network-item"&gt;${p.title}&lt;/button&gt;&lt;/li&gt;`)}&lt;/ul&gt;`;
    // In a pinned list, clicking a title selects that work
    list.querySelectorAll(".network-item").forEach((b, i) =&gt; b.addEventListener("click", () =&gt; { pinned = { paper: s.members[i] }; restore(); }));
    panel.append(html`&lt;div class="network-kicker" style="color:${themeByName.get(s.theme).color}"&gt;${s.theme}&lt;/div&gt;
      &lt;div class="network-title"&gt;${s.name}&lt;/div&gt;
      &lt;div class="network-meta"&gt;${s.members.length} ${s.members.length === 1 ? "work" : "works"}&lt;/div&gt;`, list);
    if (isPinned) panel.append(clearButton());
    else panel.append(html`&lt;p class="network-hint"&gt;Click the arc to keep this list open.&lt;/p&gt;`);
  };

  function setActive(isActive) {
    linkSel
      .attr("stroke", d =&gt; isActive(d.paper) ? d.color : "currentColor")
      .attr("stroke-opacity", d =&gt; isActive(d.paper) ? 0.75 : 0.04)
      .attr("stroke-width", d =&gt; isActive(d.paper) ? 1.8 : 1);
    dotSel
      .attr("fill-opacity", d =&gt; d.paper.type === "presentation" ? 1 : isActive(d.paper) ? 1 : 0.25)
      .attr("stroke-opacity", d =&gt; isActive(d.paper) ? 1 : 0.3)
      .attr("r", d =&gt; isActive(d.paper) ? 6.5 : 5);
    linkSel.filter(d =&gt; isActive(d.paper)).raise();
  }

  // Hover previews a selection; a click pins it until it is clicked again or cleared
  let pinned = null;
  function show(sel, isPinned) {
    if (sel.paper) { setActive(q =&gt; q === sel.paper); showPaper(sel.paper, isPinned); }
    else { const set = new Set(sel.sub.members); setActive(q =&gt; set.has(q)); showSub(sel.sub, isPinned); }
  }
  function preview(sel) { show(sel, false); }
  function restore() { if (pinned) show(pinned, true); else reset(); }
  function togglePin(sel) {
    const same = pinned && (pinned.paper ? pinned.paper === sel.paper : pinned.sub === sel.sub);
    pinned = same ? null : sel;
    restore();
  }
  function reset() {
    linkSel.attr("stroke", "currentColor").attr("stroke-opacity", 0.09).attr("stroke-width", 1);
    dotSel.attr("fill-opacity", d =&gt; d.paper.type === "presentation" ? 1 : 0.55).attr("stroke-opacity", 1).attr("r", 5);
    defaultPanel();
  }
  defaultPanel();
  return root;
}
